        var chordMap=Get(config,"chord_map",new GArray()).AsGodotArray();var previousVoicing=new GArray();double harmonic=beatsPerBar*chosen["harmonic_bars"].AsInt32();var segments=new System.Collections.Generic.List<(double Start,double Duration,Settings Section)>();foreach(var section in sections){double cursor=section["start"].AsDouble(),end=cursor+section["duration"].AsDouble();while(cursor<end-.000001){segments.Add((cursor,Math.Min(beatsPerBar,end-cursor),section));cursor+=beatsPerBar;}}
